import Image from "next/image";

/**
 * Stylised illustrations from public/assets/illustrations (generated by the scripts in
 * /scripts). Each womb picture covers a range of weeks; none is a medical depiction of a
 * specific week, so alt text stays general.
 */

type Stage = "early" | "first" | "second" | "third";

export function stageFor(week: number): Stage {
  if (week < 8) return "early";
  if (week < 14) return "first";
  if (week < 28) return "second";
  return "third";
}

export function WombArt({
  week,
  size = 200,
  priority = false,
  className,
}: {
  week: number;
  size?: number;
  priority?: boolean;
  className?: string;
}) {
  return (
    <Image
      src={`/assets/illustrations/womb-${stageFor(week)}.svg`}
      alt={`Illustration of a baby growing in the womb, around week ${week}`}
      width={size}
      height={size}
      priority={priority}
      unoptimized
      className={className}
    />
  );
}

const TOPICS = ["nutrition", "movement", "sleep", "baby", "wellbeing", "care"] as const;
export type Topic = (typeof TOPICS)[number];

const KEYWORDS: [Topic, RegExp][] = [
  ["care", /test|scan|screen|appointment|visit|midwife|doctor/i],
  ["nutrition", /food|eat|nutri|diet|folic|vitamin|iron|caffeine|alcohol|recipe/i],
  ["movement", /exercis|move|activ|yoga|walk|fit/i],
  ["sleep", /sleep|rest|tired|fatigue|night/i],
  ["baby", /baby|fetal|development|kick|growth|week/i],
  ["wellbeing", /mood|stress|mental|wellbeing|anxiety|relax|feel|partner|support|sickness|nausea|symptom/i],
];

/** Picks an illustration for an article from its words; falls back by a stable hash. */
export function topicFor(text: string): Topic {
  const match = KEYWORDS.find(([, re]) => re.test(text));
  if (match) return match[0];
  let hash = 0;
  for (const ch of text) hash = (hash * 31 + ch.charCodeAt(0)) | 0;
  return TOPICS[Math.abs(hash) % TOPICS.length];
}

const TOPIC_ALT: Record<Topic, string> = {
  nutrition: "Illustration of a bowl of fruit",
  movement: "Illustration of a pregnant woman stretching on a mat",
  sleep: "Illustration of a moon over a pillow",
  baby: "Illustration of a baby in the womb",
  wellbeing: "Illustration of a lotus flower",
  care: "Illustration of a clipboard with a heart",
};

export function TopicArt({
  topic,
  className,
  sizes = "(min-width: 1024px) 25vw, (min-width: 640px) 50vw, 100vw",
}: {
  topic: Topic;
  className?: string;
  sizes?: string;
}) {
  return (
    <Image
      src={`/assets/illustrations/topic-${topic}.svg`}
      alt={TOPIC_ALT[topic]}
      width={320}
      height={200}
      sizes={sizes}
      unoptimized
      className={className}
    />
  );
}

export function MotherArt({ className, priority }: { className?: string; priority?: boolean }) {
  return (
    <Image
      src="/assets/illustrations/mother-hero.svg"
      alt="Illustration of a pregnant woman holding her bump, surrounded by leaves and flowers"
      width={480}
      height={560}
      priority={priority}
      unoptimized
      className={className}
    />
  );
}
